import{_ as s,o as a,c as t,a2 as d}from"./chunks/framework.DqYch1Cg.js";const u=JSON.parse('{"title":"Linux、SSH 与运行环境","description":"","frontmatter":{},"headers":[],"relativePath":"概念与原理/20deploy/s_deploy_1-linux_ssh.md","filePath":"概念与原理/20deploy/s_deploy_1-linux_ssh.md","lastUpdated":1794211306000}'),o={name:"概念与原理/20deploy/s_deploy_1-linux_ssh.md"};function i(n,e,l,r,c,h){return a(),t("div",null,[...e[0]||(e[0]=[d(`<h1 id="linux、ssh-与运行环境" tabindex="-1">Linux、SSH 与运行环境 <a class="header-anchor" href="#linux、ssh-与运行环境" aria-label="Permalink to &quot;Linux、SSH 与运行环境&quot;">​</a></h1><h2 id="先理解机器-再运行命令" tabindex="-1">先理解机器，再运行命令 <a class="header-anchor" href="#先理解机器-再运行命令" aria-label="Permalink to &quot;先理解机器，再运行命令&quot;">​</a></h2><p>服务器部署至少涉及操作系统、网络、运行时、应用进程和数据目录。先确认发行版及维护周期：历史笔记中的 CentOS 7 已结束常规维护，旧 <code>yum</code>、<code>service</code>、<code>chkconfig</code> 命令不能直接当成所有 Linux 的通用步骤。以下以使用 systemd 的发行版为例，安装软件要查对应发行版文档。</p><table tabindex="0"><thead><tr><th>问题</th><th>观察命令</th><th>如何解释</th></tr></thead><tbody><tr><td>系统与内核</td><td><code>cat /etc/os-release</code>、<code>uname -r</code></td><td>软件包来源、支持周期及内核版本</td></tr><tr><td>CPU 与负载</td><td><code>uptime</code>、<code>top</code>、<code>vmstat 1</code></td><td>负载还包含不可中断等待；结合核数、CPU 和 I/O 判断</td></tr><tr><td>内存</td><td><code>free -h</code></td><td>区分 available、页缓存和应用占用，不能只看 free</td></tr><tr><td>磁盘</td><td><code>df -h</code>、<code>df -i</code>、<code>du -sh ./logs</code></td><td>空间耗尽与 inode 耗尽是不同问题</td></tr><tr><td>端口</td><td><code>ss -lntp</code></td><td>监听的是公网地址还是 loopback，进程是否符合预期</td></tr><tr><td>服务</td><td><code>systemctl status nginx</code>、<code>journalctl -u nginx -n 100</code></td><td>同时核对退出原因、时间线和应用日志</td></tr></tbody></table><p>这些读操作适合排查，但输出仍可能包含业务信息，不要直接粘贴到公开问题中。</p><h2 id="ssh-登录与权限" tabindex="-1">SSH 登录与权限 <a class="header-anchor" href="#ssh-登录与权限" aria-label="Permalink to &quot;SSH 登录与权限&quot;">​</a></h2><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 在个人电脑生成密钥；私钥留在本机，设置口令</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ssh-keygen</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -t</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ed25519</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -C</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;learning-server&quot;</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 将公钥安装到已有授权的部署账户，首次连接核对主机指纹</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ssh-copy-id</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deploy@example.com</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ssh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deploy@example.com</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>保持已有会话和云平台恢复入口，再用一个新会话验证密钥登录。确认 sudo 权限、恢复方式后，才考虑禁用密码登录和 root 直登。修改配置后先运行 <code>sshd -t</code> 检查；具体服务名可能是 <code>ssh</code> 或 <code>sshd</code>，按系统核实。</p><p>修改默认端口只能减少部分扫描噪声，不能代替密钥认证、补丁和访问控制。云安全组与主机防火墙都要核对；Ubuntu 的 UFW 和其他系统的 firewalld 不应混用教程逐条执行。</p><h2 id="目录、文件与编辑" tabindex="-1">目录、文件与编辑 <a class="header-anchor" href="#目录、文件与编辑" aria-label="Permalink to &quot;目录、文件与编辑&quot;">​</a></h2><ul><li><code>/etc</code> 放配置，<code>/var/log</code> 放日志；<code>/tmp</code> 是临时目录，不是持久化数据目录。</li><li>应用发布目录可放 <code>/srv/my-app/releases/&lt;version&gt;</code>，运行账户只获得必要读写权限。</li><li><code>ls -lah</code>、<code>pwd</code>、<code>less</code>、<code>tail -n 100</code> 用于定位；<code>cp -a</code> 可保留必要属性。删除前确认绝对路径，不把 <code>rm -rf</code> 写成习惯性修复。</li><li>Vim 最小闭环：<code>i</code> 编辑，<code>Esc</code> 退出编辑，<code>:wq</code> 保存退出，<code>:q!</code> 放弃；修改系统配置前保留副本并使用工具校验。</li><li>文件权限分 owner / group / others；目录的 x 是穿越权限。避免用 <code>chmod 777</code> 掩盖账户和目录设计问题。</li></ul><h2 id="运行环境与排障顺序" tabindex="-1">运行环境与排障顺序 <a class="header-anchor" href="#运行环境与排障顺序" aria-label="Permalink to &quot;运行环境与排障顺序&quot;">​</a></h2><p>Node 版本在仓库中声明，依赖用锁文件安装。交互式 shell 中能使用 nvm，不代表 systemd 服务能找到同一套 Node；服务配置需要明确用户、工作目录、可执行文件和环境来源。</p><p>遇到“页面打不开”，按 DNS / TLS → Nginx → 应用监听 → 数据库连接逐层验证。CPU 高、I/O 高、端口没监听、反向代理 502 的原因不同，不要先靠重启碰运气。</p><p><strong>自测：</strong> 为什么 load average 为 2 不一定表示过载？为什么 SSH 新配置必须用新会话验证？为什么服务启动不应依赖个人 shell 的初始化脚本？</p><blockquote><p>来源：<a href="https://github.com/Fridolph/Fridolph/tree/c3a1eda8e0f7fe08d8ec54e07d07db514cbfc5d7/%E9%83%A8%E7%BD%B2%E7%9B%B8%E5%85%B3%E7%9F%A5%E8%AF%86" target="_blank" rel="noreferrer">个人 Linux / SSH 旧笔记</a>；<a href="https://www.openssh.com/manual.html" target="_blank" rel="noreferrer">OpenSSH 手册</a>；<a href="https://systemd.io/" target="_blank" rel="noreferrer">systemd 文档</a>；<a href="https://www.centos.org/centos-linux-eol/" target="_blank" rel="noreferrer">CentOS Linux EOL</a>。</p></blockquote>`,16)])])}const k=s(o,[["render",i]]);export{u as __pageData,k as default};
